pub struct Celsius(f64);                          // field is private outside this module
impl Celsius {
    pub fn new(deg: f64) -> Self { Self(deg) }
    pub fn from_fahrenheit(f: f64) -> Self { Self((f - 32.0) * 5.0 / 9.0) }
    pub fn try_from_str(s: &str) -> Result<Self, std::num::ParseFloatError> {
        s.parse().map(Self)
    }
}
